import hashlib, json
from datetime import datetime, timezone

def _hash(obj) -> str:
    return hashlib.sha256(json.dumps(obj, sort_keys=True).encode()).hexdigest()

class DecisionLog:
    def __init__(self, store):
        self.store = store                         # append-only, write-once bucket
        self.prev = store.last_hash() or "0" * 64

    def record(self, case_id, doc_bytes, fields, run, decision, reasons, reviewer=None):
        entry = {
            "case_id": case_id,
            "ts": datetime.now(timezone.utc).isoformat(),
            "input_sha256": hashlib.sha256(doc_bytes).hexdigest(),
            "fields": mask_pii(fields),            # no raw Aadhaar or PAN
            "model": run.model, "prompt_version": run.prompt_version,
            "policy_clauses": run.clauses_used, "tool_calls": run.tool_calls,
            "decision": decision, "reason_codes": reasons,
            "reviewer": reviewer, "prev": self.prev}
        entry["hash"] = _hash(entry)
        self.store.append(entry)
        self.prev = entry["hash"]
        return entry["hash"]

def verify(entries) -> bool:
    """Any edit or deletion breaks the chain."""
    prev = entries[0]["prev"]
    for e in entries:
        body = {k: v for k, v in e.items() if k != "hash"}
        if e["prev"] != prev or _hash(body) != e["hash"]:
            return False
        prev = e["hash"]
    return True

import json, subprocess, pathlib

def credentials(path):
    r = subprocess.run(["c2patool", str(path)], capture_output=True, text=True)
    if r.returncode != 0 or not r.stdout.strip():
        return None
    return json.loads(r.stdout)

